script:
// Keep helpers local to this Client Script.
;(() => {
frappe.ui.form.on('Solar Design', {
  refresh(frm) {
    if (frm.is_new() && !frm.doc.design_status) frm.set_value('design_status', 'مسودة');
    if (frm.doc.design_status === 'معتمدة') frm.set_df_property('create_quotation', 'description', 'يمكن إنشاء مسودة عرض السعر بعد اعتماد التصميم.');
  },

  async calculate_design(frm) {
    frappe.dom.freeze('جاري حساب التصميم وتجهيز قائمة المكونات...');
    try {
      const d = frm.doc;
      const warnings = [];
      const manualMode = (d.design_mode || 'تصميم يدوي بالاسترنجات') === 'تصميم يدوي بالاسترنجات';
      const targetPvKw = flt(d.target_pv_kw);
      const stringCount = flt(d.string_count);
      const panelsPerString = flt(d.panels_per_string);
      const enteredPanelWatt = flt(d.panel_watt);
      const actualPanelCount = stringCount * panelsPerString;
      const actualPvKw = actualPanelCount * enteredPanelWatt / 1000;
      const hp = flt(d.pump_power_hp);
      const pump_kw = flt(d.pump_power_kw) || (hp ? hp * 0.746 : 0);
      const load_kw = flt(d.application_load_kw);
      const base_kw = Math.max(pump_kw, load_kw);
      const hours = flt(d.daily_operation_hours);
      const daily_energy = Math.max(flt(d.daily_energy_kwh), pump_kw * hours);
      const irradiance = flt(d.solar_irradiance) || 5;
      const pr = (flt(d.performance_ratio) || 75) / 100;
      const margin = (flt(d.system_margin) || 15) / 100;
      const energy_kw = daily_energy && irradiance && pr ? (daily_energy / (irradiance * pr)) * (1 + margin) : 0;
      const power_kw = base_kw ? base_kw * (1 + margin) : 0;
      const recommended_kw = Math.max(energy_kw, power_kw);
      const designPvKw = manualMode && actualPvKw ? actualPvKw : recommended_kw;

      if (!d.customer) warnings.push('اختر العميل.');
      if (!d.project_name) warnings.push('اكتب اسم أو لقب المشروع.');
      if (!d.location) warnings.push('أدخل الموقع أو المحافظة، أو راجع الإشعاع الشمسي يدويًا.');
      if (d.application_type === 'ري وطلمبات آبار' && !pump_kw) warnings.push('أدخل قدرة الطلمبة بالحصان أو بالكيلووات.');
      if (manualMode && !targetPvKw) warnings.push('أدخل القدرة التقريبية المطلوبة للمقارنة.');
      if (manualMode && !stringCount) warnings.push('أدخل عدد الاسترنجات.');
      if (manualMode && !panelsPerString) warnings.push('أدخل عدد الألواح في كل استرنج.');
      if (manualMode && !enteredPanelWatt) warnings.push('أدخل قدرة اللوح بالوات أو اختر صنف الألواح.');
      if (d.application_type === 'ري وطلمبات آبار' && !flt(d.total_dynamic_head)) warnings.push('أدخل الرفع الكلي؛ لا تعتمد على النزول الفعلي وحده.');
      if (d.application_type === 'ري وطلمبات آبار' && !flt(d.required_flow)) warnings.push('أدخل التصرف المطلوب.');
      if (!d.pump_voltage && d.application_type === 'ري وطلمبات آبار') warnings.push('جهد الطلمبة غير محدد؛ يلزم مراجعة المهندس.');
      if (!d.solar_irradiance) warnings.push('تم استخدام إشعاع افتراضي 5 ساعات ذروة/يوم؛ راجعه حسب الموقع.');
      if (!d.panel_watt) warnings.push('سيتم اختيار قدرة اللوح من الصنف أو استخدام 625 وات افتراضيًا.');
      if (!recommended_kw) warnings.push('لا توجد مدخلات كافية لحساب القدرة المقترحة.');

      await frm.set_value('pump_power_kw', pump_kw ? flt(pump_kw, 3) : 0);
      await frm.set_value('calculated_pv_kw', flt(Math.max(energy_kw, power_kw), 3));
      await frm.set_value('recommended_pv_kw', flt(designPvKw, 3));
      await frm.set_value('actual_panel_count', actualPanelCount || 0);
      await frm.set_value('actual_pv_kw', actualPvKw || 0);
      await frm.set_value('string_voc', flt(d.panel_voc) * panelsPerString);
      await frm.set_value('string_vmp', flt(d.panel_vmp) * panelsPerString);
      await frm.set_value('string_isc', flt(d.panel_isc));
      await frm.set_value('string_imp', flt(d.panel_imp));
      const electricalErrors = [];
      const electricalWarnings = [];
      if (manualMode && targetPvKw && actualPvKw && Math.abs(actualPvKw - targetPvKw) / targetPvKw > 0.10) electricalWarnings.push('القدرة الفعلية تختلف أكثر من 10% عن القدرة التقريبية.');
      if (manualMode && d.inverter_max_dc_voltage && d.string_voc && d.string_voc > d.inverter_max_dc_voltage) electricalErrors.push('جهد الاسترنج Voc أعلى من أقصى جهد DC للإنفرتر.');
      if (manualMode && d.inverter_mppt_min_voltage && d.string_vmp && d.string_vmp < d.inverter_mppt_min_voltage) electricalWarnings.push('جهد الاسترنج Vmp أقل من أقل جهد MPPT للإنفرتر.');
      if (manualMode && d.inverter_mppt_max_voltage && d.string_vmp && d.string_vmp > d.inverter_mppt_max_voltage) electricalErrors.push('جهد الاسترنج Vmp أعلى من أقصى جهد MPPT للإنفرتر.');
      if (manualMode && d.inverter_max_input_current && d.string_isc && d.string_isc > d.inverter_max_input_current) electricalErrors.push('تيار الاسترنج Isc أعلى من أقصى تيار دخل للإنفرتر.');
      const electricalStatus = electricalErrors.length ? 'غير متوافق' : (electricalWarnings.length ? 'تحذير - يحتاج مراجعة' : (actualPvKw ? 'متوافق مبدئيًا' : 'لم يتم التحقق'));
      await frm.set_value('design_check_status', electricalStatus);
      await frm.set_value('design_check_details', [...electricalErrors, ...electricalWarnings].join(' | ') || 'تم الحساب؛ يلزم اعتماد المهندس قبل التنفيذ.');
      if (electricalErrors.length) warnings.push(...electricalErrors);
      if (electricalWarnings.length) warnings.push(...electricalWarnings);
      await frm.set_value('inverter_kw', flt(base_kw ? base_kw * 1.10 : recommended_kw, 3));
      await frm.set_value('inverter_qty', 1);

      const listItems = async (filters, limit=50) => {
        const r = await frappe.call({method:'frappe.client.get_list', args:{doctype:'Item', fields:['name','item_name','item_group','stock_uom','standard_rate','brand'], filters:filters || [['Item','disabled','=',0]], limit_page_length:limit}});
        return r.message || [];
      };
      const rateOf = async (code) => {
        if (!code) return 0;
        try {
          const r = await frappe.call({method:'frappe.client.get_list', args:{doctype:'Item Price', fields:['price_list_rate','price_list'], filters:[['Item Price','item_code','=',code],['Item Price','selling','=',1]], limit_page_length:10}});
          const p = (r.message || []).find(x => flt(x.price_list_rate) > 0);
          if (p) return flt(p.price_list_rate);
        } catch (e) {}
        try { const r = await frappe.call({method:'frappe.client.get_value', args:{doctype:'Item', fieldname:'standard_rate', filters:{name:code}}}); return flt(r.message?.standard_rate); } catch(e) { return 0; }
      };
      const parseWatt = (x) => { const m = String(x || '').match(/(?:^|[^0-9])([0-9]{3,4})\s*(?:وات|watt|W)/i); return m ? flt(m[1]) : 0; };
      const parseKw = (x) => { const m = String(x || '').match(/([0-9]+(?:\.[0-9]+)?)\s*(?:كيلو|kw)/i); return m ? flt(m[1]) : 0; };
      const panelCandidates = await listItems([['Item','disabled','=',0],['Item','item_group','=','الواح']], 100);
      let panel = d.panel_item ? {name:d.panel_item} : null;
      if (!panel) {
        const preferred = String(d.preferred_brand || '').toLowerCase();
        const filtered = preferred ? panelCandidates.filter(x => String(x.item_name || '').toLowerCase().includes(preferred) || String(x.brand || '').toLowerCase().includes(preferred)) : panelCandidates;
        const candidates = filtered.length ? filtered : panelCandidates;
        panel = candidates.sort((a,b)=>parseWatt(b.item_name||b.name)-parseWatt(a.item_name||a.name))[0] || null;
      }
      if (panel) {
        const info = panel.item_name ? panel : (await frappe.call({method:'frappe.client.get',args:{doctype:'Item',name:panel.name}})).message;
        const watt = flt(d.panel_watt) || parseWatt(info?.item_name) || 625;
        const qty = manualMode && actualPanelCount ? actualPanelCount : (recommended_kw ? Math.ceil(recommended_kw * 1000 / watt) : 0);
        await frm.set_value('panel_item', panel.name);
        await frm.set_value('panel_watt', watt);
        await frm.set_value('panel_qty', qty);
        if (manualMode && !enteredPanelWatt) { await frm.set_value('actual_pv_kw', flt(actualPanelCount * watt / 1000, 3)); await frm.set_value('recommended_pv_kw', flt(actualPanelCount * watt / 1000, 3)); }
      } else { warnings.push('لم يتم العثور على صنف ألواح في مجموعة الالواح؛ اختر الصنف يدويًا.'); }

      const inverterCandidates = await listItems([['Item','disabled','=',0],['Item','item_group','=','انفرتر']], 150);
      let inverter = d.inverter_item ? {name:d.inverter_item} : null;
      if (!inverter && inverterCandidates.length && base_kw) {
        const withKw = inverterCandidates.map(x=>Object.assign({},x,{kw:parseKw(x.item_name||x.name)})).filter(x=>x.kw>0);
        const adequate=withKw.filter(x=>x.kw>=base_kw*1.05).sort((a,b)=>a.kw-b.kw); inverter=adequate[0] || null;
      }
      if (inverter) await frm.set_value('inverter_item', inverter.name); else warnings.push('لم يتم العثور على إنفرتر مناسب تلقائيًا؛ اختره يدويًا.');

      frm.clear_table('components');
      const addRow = async (type, item, qty, description, source='محسوبة') => {
        if (!qty || qty <= 0) return;
        const row = frm.add_child('components');
        row.component_type = type; row.item_code = item?.name || item || ''; row.qty = flt(qty); row.description = description || item?.item_name || ''; row.source = source;
        if (item?.stock_uom) row.uom = item.stock_uom;
        if (row.item_code) row.unit_rate = await rateOf(row.item_code);
        row.amount = flt(row.qty) * flt(row.unit_rate);
      };
      if (panel && flt(d.panel_qty)) {
        const pi = panel.item_name ? panel : (await frappe.call({method:'frappe.client.get',args:{doctype:'Item',name:panel.name}})).message;
        await addRow('ألواح شمسية', panel, d.panel_qty, pi?.item_name || 'ألواح شمسية');
      }
      if (inverter) {
        const ii = inverter.item_name ? inverter : (await frappe.call({method:'frappe.client.get',args:{doctype:'Item',name:inverter.name}})).message;
        await addRow('إنفرتر/وحدة تحكم', inverter, 1, ii?.item_name || 'إنفرتر أو وحدة تحكم');
      }
      const dc = (await listItems([['Item','disabled','=',0],['Item','item_group','=','اكسسوار']], 100)).find(x=>String(x.item_name||'').toLowerCase().includes('كابل طاقة شمسية dc'));
      if (dc && flt(d.dc_cable_length)) await addRow('كابل DC', dc, d.dc_cable_length, dc.item_name);
      else if (flt(d.dc_cable_length)) await addRow('كابل DC', null, d.dc_cable_length, 'كابل طاقة شمسية DC - يحدد الصنف والمقاس بعد مراجعة المهندس', 'يدوية');
      const comb = (await listItems([['Item','disabled','=',0],['Item','item_group','=','كومبينر']], 100))[0];
      const designPanelQty = manualMode && actualPanelCount ? actualPanelCount : flt(d.panel_qty);
      const designStringQty = manualMode && stringCount ? stringCount : (designPanelQty ? Math.ceil(designPanelQty / 14) : 0);
      const combQty = designStringQty;
      if (comb && combQty) await addRow('حماية وتجميع', comb, combQty, comb.item_name);
      else if (combQty) await addRow('حماية وتجميع', null, combQty, 'لوحة حماية وتجميع - يحدد الصنف بعد مراجعة المهندس', 'يدوية');
      if (designPanelQty) await addRow('هياكل', null, designPanelQty, 'هيكل تثبيت للألواح - يحدد التصميم والصنف حسب الموقع', 'يدوية');
      frm.refresh_field('components');
      let material = 0; (frm.doc.components || []).forEach(r=>{r.amount=flt(r.qty)*flt(r.unit_rate); material+=flt(r.amount);});
      await frm.set_value('material_cost', material);
      const totalCost = material + flt(d.labor_cost) + flt(d.transport_cost) + flt(d.other_cost);
      await frm.set_value('total_cost', totalCost);
      await frm.set_value('estimated_sale_price', totalCost * (1 + (flt(d.margin_percent)||15)/100));
      const missingPrices = (frm.doc.components || []).filter(r=>!r.unit_rate).map(r=>r.description || r.component_type);
      if (missingPrices.length) warnings.push('مكونات بلا سعر: ' + missingPrices.slice(0,5).join('، ') + (missingPrices.length>5?'...':''));
      if (base_kw && !d.total_dynamic_head && d.application_type === 'ري وطلمبات آبار') warnings.push('التصميم مبدئي فقط حتى إدخال الرفع الكلي والتصرف واعتماد المهندس.');
      if (manualMode && !d.panel_voc) warnings.push('بيانات Voc/Vmp/Isc/Imp غير مكتملة؛ التحقق الكهربائي مبدئي فقط.');
      await frm.set_value('design_warning', warnings.length ? warnings.join(' | ') : 'لا توجد تحذيرات أساسية؛ يلزم اعتماد المهندس قبل إصدار عرض نهائي.');
      await frm.save();
      frappe.msgprint({title:'تم حساب التصميم',indicator:warnings.length?'orange':'green',message:'تم تحديث القدرة المقترحة، اختيار المكونات المتاحة، وحساب التكلفة التقديرية. راجع التحذيرات ثم اعتمد التصميم.'});
    } catch (e) { console.error(e); frappe.msgprint({title:'تعذر الحساب',indicator:'red',message:e.message || String(e)}); }
    finally { frappe.dom.unfreeze(); }
  },

  async create_quotation(frm) {
    if (frm.doc.design_status !== 'معتمدة') { frappe.msgprint({title:'اعتماد مطلوب',indicator:'orange',message:'غيّر حالة التصميم إلى «معتمدة» بعد مراجعة المهندس قبل إنشاء مسودة عرض السعر.'}); return; }
    if (!frm.doc.customer) { frappe.msgprint({title:'بيانات ناقصة',indicator:'red',message:'اختر العميل أولًا.'}); return; }
    const rows = (frm.doc.components || []).filter(r=>flt(r.qty)>0);
    const missing = rows.filter(r=>!r.item_code || !flt(r.unit_rate));
    if (missing.length) { frappe.msgprint({title:'استكمال قائمة المكونات',indicator:'orange',message:'أكمل الصنف والسعر للمكونات التالية قبل إنشاء العرض: ' + missing.map(r=>r.description || r.component_type).slice(0,8).join('، ')}); return; }
    frappe.dom.freeze('جاري إنشاء مسودة عرض السعر...');
    try {
      const items = rows.map(r=>({item_code:r.item_code,qty:flt(r.qty),uom:r.uom||undefined,rate:flt(r.unit_rate),description:r.description||undefined}));
      const doc={doctype:'Quotation',quotation_to:'Customer',party_name:frm.doc.customer,title:frm.doc.project_name,custom_quotation_title:frm.doc.project_name,custom_type:'Solar',order_type:'Sales',custom_order_type_copy:'Sales',transaction_date:frappe.datetime.get_today(),valid_till:frappe.datetime.add_days(frappe.datetime.get_today(),15),items};
      const r=await frappe.call({method:'frappe.client.insert',args:{doc}});
      const q=r.message;
      if (q?.name) { await frm.set_value('linked_quotation',q.name); await frm.set_value('design_status','تحولت إلى عرض سعر'); await frm.save(); frappe.msgprint({title:'تم إنشاء المسودة',indicator:'green',message:'تم إنشاء مسودة عرض السعر: <a href="/app/quotation/'+encodeURIComponent(q.name)+'">'+q.name+'</a>'}); }
    } catch(e) { console.error(e); frappe.msgprint({title:'تعذر إنشاء العرض',indicator:'red',message:e.message || String(e)}); }
    finally { frappe.dom.unfreeze(); }
  }
});
})();

// Keep helpers local to this Client Script.
;(() => {
frappe.ui.form.on('Solar Design', {
  refresh(frm) {
    frm.add_custom_button('جلب بيانات الموقع', async () => {
      const province = String(frm.doc.site_province_center || '').trim();
      const area = String(frm.doc.site_village_area || '').trim();
      if (!province) { frappe.msgprint('اكتب المحافظة أو المركز أولًا.'); return; }
      const query = encodeURIComponent([area, province, 'مصر'].filter(Boolean).join(', '));
      frappe.show_progress('بيانات الموقع', 'جاري تحديد الموقع واستخراج البيانات...', 30, 100);
      try {
        const geoResp = await fetch('https://nominatim.openstreetmap.org/search?format=jsonv2&addressdetails=1&limit=5&countrycodes=eg&q=' + query, {headers:{'Accept':'application/json'}});
        const geoRows = await geoResp.json();
        if (!geoResp.ok || !Array.isArray(geoRows) || !geoRows.length) throw new Error('لم يتم العثور على نتيجة واضحة للموقع.');
        const place = geoRows[0];
        const lat = parseFloat(place.lat); const lon = parseFloat(place.lon);
        if (!Number.isFinite(lat) || !Number.isFinite(lon)) throw new Error('نتيجة الموقع لا تحتوي على إحداثيات صالحة.');
        frappe.show_progress('بيانات الموقع', 'تم تحديد الموقع؛ جاري جلب الشمس والارتفاع...', 65, 100);
        const powerUrl = 'https://power.larc.nasa.gov/api/temporal/climatology/point?parameters=ALLSKY_SFC_SW_DWN,T2M,WS10M&community=RE&longitude=' + lon + '&latitude=' + lat + '&format=JSON';
        const elevUrl = 'https://api.open-meteo.com/v1/elevation?latitude=' + lat + '&longitude=' + lon;
        const responses = await Promise.all([fetch(powerUrl), fetch(elevUrl)]);
        const power = await responses[0].json(); const elevationData = await responses[1].json();
        const p = power && power.properties && power.properties.parameter ? power.properties.parameter : {};
        const solar = Number(p.ALLSKY_SFC_SW_DWN && p.ALLSKY_SFC_SW_DWN.ANN || 0);
        const temp = Number(p.T2M && p.T2M.ANN || 0);
        const wind = Number(p.WS10M && p.WS10M.ANN || 0);
        const elevation = Number(elevationData && elevationData.elevation && elevationData.elevation[0] || 0);
        const display = place.display_name || [area, province, 'مصر'].filter(Boolean).join('، ');
        await frm.set_value('location', display);
        await frm.set_value('site_latitude', lat);
        await frm.set_value('site_longitude', lon);
        await frm.set_value('site_map_url', 'https://www.openstreetmap.org/?mlat=' + lat + '&mlon=' + lon + '#map=14/' + lat + '/' + lon);
        await frm.set_value('site_location_confidence', area ? 'جيدة - منطقة/قرية' : 'تقريبية - محافظة/مركز');
        await frm.set_value('site_data_status', 'تم الجلب - يحتاج مراجعة');
        await frm.set_value('site_solar_resource', solar);
        await frm.set_value('site_average_temp_c', temp);
        await frm.set_value('site_wind_speed_ms', wind);
        await frm.set_value('site_elevation_m', elevation);
        await frm.set_value('site_last_fetched_at', frappe.datetime.now_datetime());
        await frm.set_value('site_external_summary', 'الموقع: ' + display + ' | Nominatim/OpenStreetMap. الإشعاع: ' + solar.toFixed(2) + ' kWh/m²/day، الحرارة: ' + temp.toFixed(2) + ' °C، الرياح: ' + wind.toFixed(2) + ' m/s من NASA POWER. الارتفاع: ' + elevation.toFixed(1) + ' m من Open-Meteo/Copernicus DEM. البيانات مبدئية وتحتاج مراجعة.');
        frappe.hide_progress();
        frappe.msgprint({title:'تم جلب بيانات الموقع للمراجعة',indicator:'blue',message:'<div dir="rtl"><b>الموقع:</b> ' + display + '<br><b>الإحداثيات:</b> ' + lat.toFixed(6) + ', ' + lon.toFixed(6) + '<br><b>الإشعاع السنوي:</b> ' + solar.toFixed(2) + ' kWh/m²/day<br><b>الارتفاع:</b> ' + elevation.toFixed(1) + ' متر<br><br>راجع النتيجة ثم اضغط اعتماد بيانات الموقع إذا كانت مناسبة.</div>'});
        frm.refresh_fields();
      } catch (e) {
        frappe.hide_progress();
        await frm.set_value('site_data_status', 'فشل الجلب');
        frappe.msgprint({title:'تعذر جلب بيانات الموقع',indicator:'red',message:e.message || String(e)});
      }
    }, 'بيانات الموقع');
    frm.add_custom_button('عرض الخريطة', () => {
      if (frm.doc.site_map_url) window.open(frm.doc.site_map_url, '_blank'); else frappe.msgprint('اجلب بيانات الموقع أولًا.');
    }, 'بيانات الموقع');
    frm.add_custom_button('اعتماد بيانات الموقع', async () => {
      if (!frm.doc.site_latitude || !frm.doc.site_longitude) { frappe.msgprint('اجلب بيانات الموقع أولًا.'); return; }
      await frm.set_value('site_data_status', 'معتمد مبدئيًا');
