// Keep helpers local to this Client Script.
;(() => {
const fm_party_map = {
    'العميل': 'Customer',
    'المورد': 'Supplier',
    'الموظف': 'Employee'
};

const fm_error = (e) => (e && e.message) ? e.message : String(e);

const fm_get_bank_account = async (frm) => {
    if (!frm.doc.mode_of_payment) throw new Error('اختر البنك أو الصندوق أولًا.');
    const r = await frappe.call({method: 'frappe.client.get', args: {doctype: 'Mode of Payment', name: frm.doc.mode_of_payment}});
    const account = (r.message?.accounts || []).find(x => x.company === frm.doc.company)?.default_account;
    if (!account) throw new Error('طريقة الدفع لا تحتوي على حساب افتراضي للشركة الحالية.');
    const a = await frappe.call({method: 'frappe.client.get', args: {doctype: 'Account', name: account}});
    if (a.message?.is_group || a.message?.disabled) throw new Error('حساب البنك أو الصندوق غير صالح أو تجميعي.');
    return account;
};

const fm_get_party_account = async (frm, party_type, party) => {
    const r = await frappe.call({method: 'erpnext.accounts.party.get_party_account', args: {party_type, party, company: frm.doc.company}});
    if (!r.message) throw new Error('تعذر تحديد حساب الطرف الافتراضي للشركة.');
    return r.message;
};

const fm_get_valid_cost_center = async (frm) => {
    if (frm.doc.cost_center) {
        const current = await frappe.call({method: 'frappe.client.get', args: {doctype: 'Cost Center', name: frm.doc.cost_center}});
        if (current.message && !current.message.is_group && !current.message.disabled) return frm.doc.cost_center;
    }
    const r = await frappe.call({method: 'frappe.client.get_list', args: {
        doctype: 'Cost Center',
        filters: {company: frm.doc.company, is_group: 0, disabled: 0},
        fields: ['name'], order_by: 'lft asc', limit_page_length: 1
    }});
    const leaf = (r.message || [])[0];
    if (!leaf) throw new Error('لا يوجد مركز تكلفة تفصيلي صالح للشركة.');
    return leaf.name;
};

const fm_validate_lines = (frm) => {
    const lines = frm.doc.custom_accounting_lines || [];
    if (lines.length < 2) throw new Error('أضف سطرين على الأقل في تفاصيل القيد.');
    let debit = 0, credit = 0;
    lines.forEach((line, idx) => {
        const d = Number(line.debit || 0), c = Number(line.credit || 0);
        if (!line.account) throw new Error('اختر الحساب في السطر رقم ' + (idx + 1) + '.');
        if (d < 0 || c < 0 || (d > 0 && c > 0) || (d === 0 && c === 0)) {
            throw new Error('كل سطر يجب أن يحتوي على مدين أو دائن فقط في السطر رقم ' + (idx + 1) + '.');
        }
        debit += d;
        credit += c;
    });
    if (Math.abs(debit - credit) > 0.01) throw new Error('القيد غير متوازن.');
    return {debit, credit};
};

const fm_set_visibility = (frm) => {
    const complex = frm.doc.custom_entry_mode === 'قيد محاسبي متعدد البنود';
    const category = frm.doc.custom_party_category || '';
    frm.doc.party_type = fm_party_map[category] || null;
    if (frm.fields_dict.party) frm.set_df_property('party', 'options', fm_party_map[category] || '');
    ['mode_of_payment', 'custom_party_category', 'party', 'counterpart_account'].forEach(fieldname => {
        if (frm.fields_dict[fieldname]) frm.set_df_property(fieldname, 'hidden', complex);
    });
    if (frm.fields_dict.custom_accounting_lines) {
        frm.set_df_property('custom_accounting_lines', 'hidden', !complex);
        frm.set_df_property('custom_accounting_lines', 'reqd', complex);
    }
    if (frm.fields_dict.amount) {
        frm.set_df_property('amount', 'reqd', !complex);
        frm.set_df_property('amount', 'read_only', complex);
    }
};

const fm_set_link = async (doctype, name, fieldname, value) => {
    await frappe.call({method: 'frappe.client.set_value', args: {doctype, name, fieldname, value}});
};

const fm_find_existing_link = async (name) => {
    const [pe, je] = await Promise.all([
        frappe.call({method: 'frappe.client.get_list', args: {doctype: 'Payment Entry', filters: {custom_financial_movement: name}, fields: ['name','docstatus'], limit_page_length: 2}}),
        frappe.call({method: 'frappe.client.get_list', args: {doctype: 'Journal Entry', filters: {custom_financial_movement: name}, fields: ['name','docstatus'], limit_page_length: 2}})
    ]);
    return {payment: (pe.message || [])[0] || null, journal: (je.message || [])[0] || null};
};

const fm_create_payment_entry = async (frm, bank_account) => {
    const category = frm.doc.custom_party_category;
    const party_type = fm_party_map[category];
    if (!party_type || !['Customer', 'Supplier'].includes(party_type)) return null;
    if (!frm.doc.party) throw new Error('اختر العميل أو المورد.');
    if (category === 'العميل' && frm.doc.movement_type !== 'وارد') throw new Error('تحصيل العميل يجب أن يكون واردًا.');
    if (category === 'المورد' && frm.doc.movement_type !== 'منصرف') throw new Error('دفع المورد يجب أن يكون منصرفًا.');
    const party_account = await fm_get_party_account(frm, party_type, frm.doc.party);
    const payment_type = frm.doc.movement_type === 'وارد' ? 'Receive' : 'Pay';
    const doc = {
        doctype: 'Payment Entry',
        payment_type,
        posting_date: frm.doc.posting_date,
        company: frm.doc.company,
        mode_of_payment: frm.doc.mode_of_payment,
        party_type,
        party: frm.doc.party,
        paid_amount: Number(frm.doc.amount),
        received_amount: Number(frm.doc.amount),
        paid_from: payment_type === 'Receive' ? party_account : bank_account,
        paid_to: payment_type === 'Receive' ? bank_account : party_account,
        remarks: frm.doc.remarks,
        reference_no: frm.doc.reference_no || '',
        reference_date: frm.doc.reference_date || null,
        project: frm.doc.project || null,
        cost_center: frm.doc.cost_center || null,
        custom_financial_movement: frm.doc.name,
        custom_payment_stage: frm.doc.custom_payment_stage || null
    };
    if (frm.doc.reference_doctype && frm.doc.reference_name) {
        doc.references = [{reference_doctype: frm.doc.reference_doctype, reference_name: frm.doc.reference_name, allocated_amount: Number(frm.doc.amount)}];
    }
    const ins = await frappe.call({method: 'frappe.client.insert', args: {doc}});
    if (!ins.message) throw new Error('تعذر إنشاء سند الدفع.');
    const sub = await frappe.call({method: 'frappe.client.submit', args: {doc: ins.message}});
    if (!sub.message) throw new Error('تم إنشاء سند الدفع لكن تعذر اعتماده. راجعه قبل المتابعة.');
    return {doctype: 'Payment Entry', name: sub.message.name};
};

const fm_make_je_rows = async (frm, bank_account, cost_center) => {
    const rows = frm.doc.custom_accounting_lines || [];
    return rows.map(line => ({
        account: line.account,
        account_currency: 'EGP',
        exchange_rate: 1,
        debit_in_account_currency: Number(line.debit || 0),
        credit_in_account_currency: Number(line.credit || 0),
        debit: Number(line.debit || 0),
        credit: Number(line.credit || 0),
        cost_center: line.cost_center || cost_center,
        project: line.project || frm.doc.project || null,
        user_remark: line.remarks || frm.doc.remarks || null,
        party_type: line.party_type || null,
        party: line.party || null
    }));
};

const fm_create_journal_entry = async (frm, bank_account, cost_center) => {
    const complex = frm.doc.custom_entry_mode === 'قيد محاسبي متعدد البنود';
    let accounts;
    if (complex) {
        fm_validate_lines(frm);
        accounts = await fm_make_je_rows(frm, bank_account, cost_center);
    } else {
        if (!frm.doc.counterpart_account) throw new Error('اختر حساب المصروف أو الحساب المقابل.');
        const check = await frappe.call({method: 'frappe.client.get', args: {doctype: 'Account', name: frm.doc.counterpart_account}});
        if (check.message?.is_group || check.message?.disabled) throw new Error('الحساب المقابل غير صالح أو تجميعي.');
        const expenseRow = {
            account: frm.doc.counterpart_account,
            account_currency: 'EGP', exchange_rate: 1,
            debit_in_account_currency: frm.doc.movement_type === 'منصرف' ? Number(frm.doc.amount) : 0,
            credit_in_account_currency: frm.doc.movement_type === 'وارد' ? Number(frm.doc.amount) : 0,
            debit: frm.doc.movement_type === 'منصرف' ? Number(frm.doc.amount) : 0,
            credit: frm.doc.movement_type === 'وارد' ? Number(frm.doc.amount) : 0,
            cost_center, project: frm.doc.project || null, user_remark: frm.doc.remarks || null
        };
        if (frm.doc.custom_party_category === 'الموظف' && frm.doc.party) {
            expenseRow.party_type = 'Employee';
            expenseRow.party = frm.doc.party;
        }
        accounts = [expenseRow, {
            account: bank_account,
            account_currency: 'EGP', exchange_rate: 1,
            debit_in_account_currency: frm.doc.movement_type === 'وارد' ? Number(frm.doc.amount) : 0,
            credit_in_account_currency: frm.doc.movement_type === 'منصرف' ? Number(frm.doc.amount) : 0,
            debit: frm.doc.movement_type === 'وارد' ? Number(frm.doc.amount) : 0,
            credit: frm.doc.movement_type === 'منصرف' ? Number(frm.doc.amount) : 0,
            cost_center, project: frm.doc.project || null, user_remark: frm.doc.remarks || null
        }];
    }
    const ins = await frappe.call({method: 'frappe.client.insert', args: {doc: {
        doctype: 'Journal Entry', voucher_type: 'Journal Entry', company: frm.doc.company,
        posting_date: frm.doc.posting_date, user_remark: frm.doc.remarks,
        custom_financial_movement: frm.doc.name,
