};

const fm_create_and_post = async (frm) => {
    if (frm.is_new()) await frm.save();
    if (frm.is_dirty()) await frm.save();
    if (frm.doc.custom_payment_entry_reference || frm.doc.custom_journal_entry_reference || frm.doc.created_document) {
        frappe.msgprint('تم إنشاء مستند محاسبي لهذه الحركة من قبل.');
        return;
    }
    const existing = await fm_find_existing_link(frm.doc.name);
    if (existing.payment || existing.journal) throw new Error('يوجد مستند محاسبي مرتبط بهذه الحركة بالفعل.');
    if (!frm.doc.amount || Number(frm.doc.amount) <= 0) throw new Error('أدخل مبلغًا أكبر من صفر.');
    const bank_account = await fm_get_bank_account(frm);
    const cost_center = await fm_get_valid_cost_center(frm);
    const category = frm.doc.custom_party_category;
    const linked = category && ['العميل','المورد'].includes(category)
        ? await fm_create_payment_entry(frm, bank_account)
        : await fm_create_journal_entry(frm, bank_account, cost_center);
    const key = 'FM|' + frm.doc.name;
    await fm_set_link('Financial Movement', frm.doc.name, 'created_document_type', linked.doctype);
    await fm_set_link('Financial Movement', frm.doc.name, 'created_document', linked.name);
    await fm_set_link('Financial Movement', frm.doc.name, 'custom_operation_key', key);
    await fm_set_link('Financial Movement', frm.doc.name, 'posting_status', 'Posted');
    await fm_set_link('Financial Movement', frm.doc.name, linked.doctype === 'Payment Entry' ? 'custom_payment_entry_reference' : 'custom_journal_entry_reference', linked.name);
    await fm_set_link('Financial Movement', frm.doc.name, 'custom_posting_note', 'تم إنشاء واعتماد ' + linked.doctype + ' وربطه بهذه الحركة المالية.');
    await frm.reload_doc();
    frappe.msgprint({title: 'تم الترحيل بنجاح', message: 'تم إنشاء واعتماد المستند ' + linked.name + ' مرة واحدة وربطه بالحركة المالية.', indicator: 'green'});
};

const fm_open_linked = (frm) => {
    const dt = frm.doc.created_document_type, name = frm.doc.created_document;
    if (dt && name) frappe.set_route('Form', dt, name);
};

const fm_cancel_linked = async (frm) => {
    const dt = frm.doc.created_document_type, name = frm.doc.created_document;
    if (!dt || !name) throw new Error('لا يوجد مستند محاسبي مرتبط.');
    const linked = await frappe.call({method: 'frappe.client.get', args: {doctype: dt, name}});
    if (linked.message?.docstatus === 1) await frappe.call({method: 'frappe.client.cancel', args: {doctype: dt, name}});
    await fm_set_link('Financial Movement', frm.doc.name, 'posting_status', 'Cancelled');
    await fm_set_link('Financial Movement', frm.doc.name, 'custom_posting_note', 'تم إلغاء المستند المحاسبي المرتبط بهذه الحركة.');
    await frm.reload_doc();
    frappe.msgprint({title: 'تم الإلغاء', message: 'تم إلغاء المستند المرتبط وتحديث حالة الحركة.', indicator: 'orange'});
};

frappe.ui.form.on('Financial Movement', {
    onload(frm) {
        if (!frm.doc.company) frm.set_value('company', 'Solar City');
        if (!frm.doc.custom_entry_mode) frm.set_value('custom_entry_mode', 'حركة بسيطة');
        if (frm.is_new() && !frm.doc.custom_party_category && frm.doc.custom_entry_mode !== 'قيد محاسبي متعدد البنود') frm.set_value('custom_party_category', 'العميل');
        fm_set_visibility(frm);
    },
    refresh(frm) {
        fm_set_visibility(frm);
        frm.remove_custom_button('إنشاء مسودة قيد');
        frm.remove_custom_button('إنشاء قيد يومية');
        frm.remove_custom_button('تسجيل وترحيل العملية');
        if (!frm.is_new() && !frm.doc.created_document) {
            frm.add_custom_button('تسجيل وترحيل العملية', async () => {
                try { await fm_create_and_post(frm); } catch (e) { frappe.msgprint({title:'تعذر الترحيل',message:fm_error(e),indicator:'red'}); }
            }, 'المحاسبة');
        }
        if (frm.doc.created_document) {
            frm.add_custom_button('فتح المستند المرتبط', () => fm_open_linked(frm), 'المحاسبة');
            if (frm.doc.posting_status !== 'Cancelled') frm.add_custom_button('إلغاء المستند المرتبط', async () => {
                try { await fm_cancel_linked(frm); } catch (e) { frappe.msgprint({title:'تعذر الإلغاء',message:fm_error(e),indicator:'red'}); }
            }, 'المحاسبة');
        }
    },
    custom_entry_mode(frm) { fm_set_visibility(frm); },
    movement_type(frm) { fm_set_visibility(frm); },
    custom_party_category(frm) { fm_set_visibility(frm); },
    before_submit(frm) {
        if (!frm.doc.created_document) throw new Error('لا تعتمد الحركة مباشرة. استخدم «تسجيل وترحيل العملية» لإنشاء المستند المحاسبي وربطه أولًا.');
    },
    validate(frm) {
        const complex = frm.doc.custom_entry_mode === 'قيد محاسبي متعدد البنود';
        if (complex) {
            const totals = fm_validate_lines(frm);
            frm.doc.amount = totals.debit;
            return;
        }
        if (!frm.doc.mode_of_payment) throw new Error('اختر البنك أو الصندوق أولًا.');
        if (!Number(frm.doc.amount || 0)) throw new Error('أدخل مبلغًا أكبر من صفر.');
        if (frm.doc.custom_party_category && !frm.doc.party) throw new Error('اختر الجهة أو امسح نوع الجهة لاستخدام حساب مقابل.');
        if (frm.doc.custom_party_category === 'الموظف' && !frm.doc.counterpart_account) throw new Error('اختر حساب المصروف لحركة الموظف.');
        if (!frm.doc.custom_party_category && !frm.doc.counterpart_account) throw new Error('اختر الطرف أو الحساب المقابل.');
        if (frm.doc.custom_party_category === 'العميل' && frm.doc.movement_type !== 'وارد') throw new Error('تحصيل العميل يجب أن يكون واردًا.');
        if (frm.doc.custom_party_category === 'المورد' && frm.doc.movement_type !== 'منصرف') throw new Error('دفع المورد يجب أن يكون منصرفًا.');
        if (frm.doc.custom_party_category === 'الموظف' && frm.doc.movement_type !== 'منصرف') throw new Error('دفع الموظف يجب أن يكون منصرفًا.');
    }
});
})();

