function scl_company_data(frm) {
  return frappe.call({method:'frappe.client.get', args:{doctype:'Company', name:frm.doc.company || 'Solar City'}}).then(r => r.message || {});
}

function scl_prepare_layout(source, company) {
  const parser = new DOMParser();
  const parsed = parser.parseFromString(source || '<div id="document-container"></div>', 'text/html');
  const container = parsed.querySelector('#document-container') || parsed.body.firstElementChild;
  if (!container) frappe.throw('لم يتم العثور على التخطيط الأصلي');
  container.querySelectorAll('.no-print').forEach(el => el.remove());
  const header = container.querySelector('header');
  if (header) {
    const h1 = header.querySelector('h1');
    const h2 = header.querySelector('h2');
    const p = header.querySelector('p');
    if (h1) h1.textContent = company.company_name || 'Solar City';
    if (h2) h2.textContent = 'سولار سيتي للطاقة الشمسية و حلول المياه';
    if (p) p.textContent = 'قائمة أسعار العملاء — نفس تنسيق القائمة الأصلي';
    const logo = header.querySelector('#logo-img');
    if (logo && company.company_logo) logo.setAttribute('src', company.company_logo);
    const upload = header.querySelector('#logo-upload');
    if (upload) upload.remove();
  }
  const date = container.querySelector('#current-date');
  if (date) date.textContent = new Intl.DateTimeFormat('ar-EG',{dateStyle:'short'}).format(new Date());
  return container;
}

function scl_text(cell, value) {
  if (cell) cell.textContent = value === undefined || value === null ? '' : String(value);
}
function scl_number(value) { return Number(value || 0); }
function scl_num_text(value) { return String(value === undefined || value === null ? 0 : value); }

function scl_apply_tables_to_layout(container, doc) {
  const tables = container.querySelectorAll('table');
  if (tables.length < 13) return container;
  const inv = doc.custom_inverter_rows || [];
  tables[0].querySelectorAll('tbody tr').forEach((tr, i) => {
    const r = inv[i]; if (!r) return;
    [r.hp, r.kw, r.delexi_price, r.fricon_price, r.vichi_price].forEach((v,j)=>scl_text(tr.cells[j], scl_num_text(v)));
  });
  const board = doc.custom_board_rows || [];
  const br = tables[1].querySelectorAll('tr');
  if (br[0]) board.forEach((r,i)=>scl_text(br[0].cells[i], r.range_label));
  if (br[1]) board.forEach((r,i)=>scl_text(br[1].cells[i], scl_num_text(r.customer_price)));
  const dc = doc.custom_dc_rows || [];
  tables[2].querySelectorAll('tbody tr').forEach((tr,i)=>{
    const r=dc[i]; if(!r)return;
    scl_text(tr.cells[0],r.brand); scl_text(tr.cells[1],r.specification_1); scl_text(tr.cells[2],scl_num_text(r.price_1)); scl_text(tr.cells[3],r.specification_2); scl_text(tr.cells[4],scl_num_text(r.price_2));
  });
  const comb = doc.custom_combiner_rows || [];
  const cr = tables[3].querySelectorAll('tr');
  [1,3].forEach((rowIndex, block)=>{
    const tr=cr[rowIndex]; if(!tr)return;
    for(let i=0;i<5;i++){const r=comb[block*5+i];if(r){scl_text(tr.cells[i],r.line_count);scl_text(cr[rowIndex+1]?.cells[i],scl_num_text(r.customer_price));}}
  });
  const marine=doc.custom_marine_rows||[];
  tables[4].querySelectorAll('tbody tr').forEach((tr,i)=>{
    const r=marine[i];if(!r)return;
    [r.size,r.turen_price,r.sival_price,r.power_price,r.pm_price,r.ontel_price].forEach((v,j)=>scl_text(tr.cells[j],j? scl_num_text(v):v));
  });
  const iron=doc.custom_iron_pipe_rows||[];
  tables[5].querySelectorAll('tbody tr').forEach((tr,i)=>{
    const r=iron[i];if(!r)return;
    [r.thickness,r.inch_3_price,r.inch_4_price,r.inch_5_price,r.inch_6_price].forEach((v,j)=>scl_text(tr.cells[j],j?scl_num_text(v):v));
  });
  const plasticSets=[doc.custom_sudarshan_rows||[],doc.custom_eidoul_rows||[],doc.custom_storal_rows||[]];
  [6,7,8].forEach((ti,si)=>tables[ti].querySelectorAll('tbody tr').forEach((tr,i)=>{const r=plasticSets[si][i];if(r){scl_text(tr.cells[0],r.size);scl_text(tr.cells[1],scl_num_text(r.customer_price));}}));
  const starts=doc.custom_start_rows||[];
  tables[9].querySelectorAll('tbody tr').forEach((tr,i)=>{const r=starts[i];if(r){scl_text(tr.cells[0],r.item_name);scl_text(tr.cells[1],scl_num_text(r.stainless_price));scl_text(tr.cells[2],scl_num_text(r.iron_price));}});
  const ends=doc.custom_end_rows||[];
  tables[10].querySelectorAll('tbody tr').forEach((tr,i)=>{const r=ends[i];if(r){scl_text(tr.cells[0],r.item_name);scl_text(tr.cells[1],scl_num_text(r.stainless_price));if(r.notes&&tr.cells[2])scl_text(tr.cells[2],r.iron_price || r.notes);else scl_text(tr.cells[2],scl_num_text(r.iron_price));}});
  const elbows=doc.custom_elbow_rows||[];
  tables[11].querySelectorAll('tbody tr').forEach((tr,i)=>{const r=elbows[i];if(r){scl_text(tr.cells[0],r.item_name);scl_text(tr.cells[1],scl_num_text(r.iron_price));}});
  const ropes=doc.custom_rope_rows||[];
  const rr=tables[12].querySelectorAll('tbody tr');
  ropes.forEach((r,i)=>{const tr=rr[i+1];if(!tr)return;const cells=tr.cells;if(cells.length>=4){scl_text(cells[0],r.welding_type);scl_text(cells[1],scl_num_text(r.welding_price));scl_text(cells[2],r.rope_size);scl_text(cells[3],scl_num_text(r.rope_price));}else if(cells.length===3){scl_text(cells[1],r.rope_size);scl_text(cells[2],scl_num_text(r.rope_price));}});
  return container;
}

function scl_layout_from_preview(wrapper) {
  const root = wrapper.find('#document-container')[0];
  return root ? '<!--SCL_LAYOUT_START-->' + root.outerHTML + '<!--SCL_LAYOUT_END-->' : '';
}

async function scl_render_preview(frm) {
  const field = frm.fields_dict.custom_original_preview;
  if (!field) return;
  const company = await scl_company_data(frm);
  let container = scl_prepare_layout(frm.doc.custom_layout_html, company);
  // Always synchronize the visible HTML tables with the latest child-table prices.
  scl_apply_tables_to_layout(container, frm.doc);
  const wrapper = field.$wrapper;
  wrapper.html('<style id="scl-form-original-style">' + SCL_CSS + '</style><div class="scl-form-toolbar" dir="rtl"><button type="button" class="scl-form-tables">إعادة بناء العرض من الجداول</button><button type="button" class="scl-form-edit">تفعيل الخلايا</button><button type="button" class="scl-form-save">حفظ التعديلات داخل القائمة</button><button type="button" class="scl-form-publish">حفظ ونشر التحديث</button><button type="button" class="scl-form-print">طباعة / PDF</button><span class="scl-form-status"></span></div><div id="scl-form-layout-container"></div>');
  wrapper.find('#scl-form-layout-container').append(container);
  wrapper.css({'direction':'rtl','width':'100%'});
  let editing = false;
  const cells = () => wrapper.find('#document-container .editable');
  wrapper.find('.scl-form-edit').on('click', () => {
    editing = !editing;
    cells().attr('contenteditable', editing ? 'true' : 'false').toggleClass('scl-cell-active', editing);
    wrapper.find('.scl-form-edit').text(editing ? 'إيقاف تعديل الخلايا' : 'تفعيل الخلايا');
  });
  wrapper.find('.scl-form-print').on('click', () => window.print());
  wrapper.find('.scl-form-tables').on('click', async () => {
    container = scl_prepare_layout(frm.doc.custom_layout_html, company);
    scl_apply_tables_to_layout(container, frm.doc);
    wrapper.find('#scl-form-layout-container').empty().append(container);
    wrapper.find('.scl-form-status').text('تم تحديث المعاينة من جداول ERPNext');
  });
  const savePreview = async publish => {
    try {
      // Build from the latest pricing tables before saving, so old HTML cannot overwrite new prices.
      let synced = scl_prepare_layout(frm.doc.custom_layout_html, company);
      scl_apply_tables_to_layout(synced, frm.doc);
      const html = '<!--SCL_LAYOUT_START-->' + synced.outerHTML + '<!--SCL_LAYOUT_END-->';
      if (!html || html.length < 500) throw new Error('تعذر بناء التخطيط الأصلي');
      frm.set_value('custom_layout_html', html);
      await frm.save();
      if (publish) {
        const page = (await frappe.call({method:'frappe.client.get', args:{doctype:'Web Page', name:'قائمة-أسعار-سولار-سيتي'}})).message;
        if (page) {
          const start = page.main_section_html.indexOf('<!--SCL_LAYOUT_START-->');
          const end = page.main_section_html.indexOf('<!--SCL_LAYOUT_END-->');
          if (start >= 0 && end > start) page.main_section_html = page.main_section_html.slice(0,start) + html + page.main_section_html.slice(end + '<!--SCL_LAYOUT_END-->'.length);
          await frappe.call({method:'frappe.client.save', args:{doc:page}});
        }
        await frappe.call({method:'frappe.client.set_value', args:{doctype:'Public Price List',name:frm.doc.name,fieldname:{status:'منشورة',published_at:frappe.datetime.now_datetime(),published_by:frappe.session.user}}});
      }
      wrapper.find('.scl-form-status').text(publish ? 'تم حفظ التعديلات ونشرها للرابط العام' : 'تم حفظ التعديلات داخل ERPNext');
      setTimeout(()=>wrapper.find('.scl-form-status').text(''),5000);
    } catch (e) { wrapper.find('.scl-form-status').text('تعذر الحفظ: ' + (e.message || 'خطأ غير معروف')); }
  };
  wrapper.find('.scl-form-save').on('click', () => savePreview(false));
  wrapper.find('.scl-form-publish').on('click', () => savePreview(true));
}

frappe.ui.form.on('Public Price List', {
  refresh(frm) {
    if (!frm.is_new()) scl_render_preview(frm);
  }
});
})();

