const ast_generate = async (frm) => {
    if (!frm.doc.company) await frm.set_value('company', 'Solar City');
    if (!frm.doc.from_date || !frm.doc.to_date) throw new Error('أدخل تاريخ البداية وتاريخ النهاية.');
    if (frm.doc.from_date > frm.doc.to_date) throw new Error('تاريخ البداية يجب أن يسبق تاريخ النهاية.');
    const target = ast_get_target_filters(frm);
    const base = Object.assign({company: frm.doc.company}, target);
    const current = await ast_run_gl(Object.assign(base, {from_date: frm.doc.from_date, to_date: frm.doc.to_date}));
    let opening = 0;
    if (frm.doc.include_opening) {
        const previous = await ast_run_gl(Object.assign(base, {from_date: '1900-01-01', to_date: ast_prev_date(frm.doc.from_date)}));
        opening = (previous.result || []).reduce((sum, row) => sum + ast_num(row.debit) - ast_num(row.credit), 0);
    }
    const raw_source = (current.result || []).filter(row => row.posting_date || row.voucher_no);
    // تجميع سطور الأستاذ العام لنفس المستند حتى لا تتكرر الفاتورة عند تعدد حسابات القيد.
    const raw_index = new Map();
    for (const entry of raw_source) {
        const key = [entry.posting_date || '', entry.voucher_type || '', entry.voucher_no || ''].join('|');
        if (!raw_index.has(key)) raw_index.set(key, Object.assign({}, entry));
        else {
            const existing = raw_index.get(key);
            existing.debit = ast_num(existing.debit) + ast_num(entry.debit);
            existing.credit = ast_num(existing.credit) + ast_num(entry.credit);
        }
    }
    const raw = Array.from(raw_index.values());
    const grouped = [];
    let debit_total = 0;
    let credit_total = 0;
    let running = opening;
    let active_key = null;
    let group_rows = [];
    const flush_group = () => {
        if (!group_rows.length) return;
        const g_debit = group_rows.reduce((s, x) => s + ast_num(x.debit), 0);
        const g_credit = group_rows.reduce((s, x) => s + ast_num(x.credit), 0);
        grouped.push({
            row_type: 'إجمالي مجموعة',
            group_label: 'إجمالي المجموعة',
            remarks: 'إجمالي المستند',
            group_debit_total: g_debit,
            group_credit_total: g_credit,
            debit: g_debit,
            credit: g_credit,
            balance: group_rows[group_rows.length - 1].balance
        });
        group_rows = [];
    };
    for (const row of raw) {
        const key = [row.posting_date || '', row.voucher_type || '', row.voucher_no || ''].join('|');
        if (active_key !== null && key !== active_key) flush_group();
        active_key = key;
        const debit = ast_num(row.debit);
        const credit = ast_num(row.credit);
        debit_total += debit;
        credit_total += credit;
        running += debit - credit;
        const invoice = await ast_get_invoice(row.voucher_type, row.voucher_no);
        if (invoice && (invoice.items || []).length) {
            const header = ast_invoice_header(row, invoice, running, debit, credit);
            grouped.push(header);
            group_rows.push(header);
            for (const item of invoice.items) grouped.push(ast_invoice_item_row(row, invoice, item, running));
        } else {
            const mapped = {
                row_type: 'حركة',
                posting_date: row.posting_date,
                voucher_type: row.voucher_type || '',
                voucher_no: row.voucher_no || '',
                group_label: (row.voucher_type || '') + (row.voucher_no ? ' — '+row.voucher_no : ''),
                remarks: (await ast_get_voucher_description(row.voucher_type, row.voucher_no)) || row.remarks || row.against || row.voucher_subtype || row.account || '',
                account: row.account,
                party_type: row.party_type || '',
                party: row.party || row.party_name || '',
                debit,
                credit,
                balance: running,
                project: row.project || '',
                cost_center: row.cost_center || ''
            };
            grouped.push(mapped);
            group_rows.push(mapped);
        }
    }
    flush_group();
    frm.clear_table('rows');
    grouped.forEach(row => frm.add_child('rows', row));
    const closing = opening + debit_total - credit_total;
    let status = 'متزن';
    if (frm.doc.statement_type === 'حساب') status = closing > 0 ? 'مدين' : closing < 0 ? 'دائن' : 'متزن';
    else status = closing > 0 ? 'عليه' : closing < 0 ? 'له' : 'متزن';
    frm.doc.opening_balance = opening;
    frm.doc.total_debit = debit_total;
    frm.doc.total_credit = credit_total;
    frm.doc.closing_balance = closing;
    frm.doc.balance_status = status;
    frm.doc.generated_on = frappe.datetime.now_datetime();
    frm.doc.generated_by = frappe.session.user;
    frm.doc.report_status = 'تم التوليد';
    await frm.save();
    frm.refresh_field('rows');
    frappe.show_alert({message: 'تم توليد كشف الحساب التفصيلي: '+raw.length+' مستندًا و'+grouped.filter(x => x.row_type === 'بند فاتورة').length+' بند فاتورة.', indicator: 'green'});
};

