;(() => {
const solarcity_followup_parse_time = (value) => {
    const raw = String(value || '').trim();
    if (!raw) return null;
    const arabic = raw.match(/(\d{1,2})\s*[:.]\s*(\d{1,2})\s*(ص|م|AM|PM)?/i);
    if (!arabic) {
        const iso = raw.match(/(?:\d{4}-\d{2}-\d{2}\s+)?(\d{1,2}):(\d{2})/);
        if (!iso) return null;
        return String(Number(iso[1])).padStart(2, '0') + ':' + iso[2] + ':00';
    }
    let hour = Number(arabic[1]);
    const minute = Number(arabic[2]);
    const period = (arabic[3] || '').toUpperCase();
    if (minute > 59 || hour > 23) return null;
    if (period === 'م' || period === 'PM') hour = hour === 12 ? 12 : hour + 12;
    if ((period === 'ص' || period === 'AM') && hour === 12) hour = 0;
    return String(hour).padStart(2, '0') + ':' + String(minute).padStart(2, '0') + ':00';
};

const solarcity_followup_sync = (frm) => {
    const date = frm.doc.custom_موعد_المتابعة_القادمة_تاريخ;
    const time = frm.doc.custom_موعد_المتابعة_القادمة_وقت_ادخال;
    const canonical = frm.doc.custom_موعد_المتابعة_القادمة_وقت;
    if (date && time) {
        const parsed = solarcity_followup_parse_time(time);
        if (parsed) {
            const value = date + ' ' + parsed;
            if (value !== canonical) frm.set_value('custom_موعد_المتابعة_القادمة_وقت', value);
            return value;
        }
    }
    return canonical || null;
};

const solarcity_followup_display = (frm) => {
    ['custom_موعد_المتابعة_القادمة', 'custom_موعد_المتابعة_القادمة_ساعة', 'custom_موعد_المتابعة_القادمة_عرض'].forEach(fieldname => {
        if (frm.fields_dict[fieldname]) frm.set_df_property(fieldname, 'hidden', 1);
    });
    if (frm.fields_dict.custom_موعد_المتابعة_القادمة_تاريخ) {
        frm.set_df_property('custom_موعد_المتابعة_القادمة_تاريخ', 'hidden', 0);
        frm.set_df_property('custom_موعد_المتابعة_القادمة_تاريخ', 'description', 'اختر تاريخ المتابعة القادمة.');
    }
    if (frm.fields_dict.custom_موعد_المتابعة_القادمة_وقت_ادخال) {
        frm.set_df_property('custom_موعد_المتابعة_القادمة_وقت_ادخال', 'hidden', 0);
        frm.set_df_property('custom_موعد_المتابعة_القادمة_وقت_ادخال', 'description', 'اختر الوقت من الساعة الدائرية بالدقيقة و ص/م.');
    }
    if (frm.fields_dict.custom_موعد_المتابعة_القادمة_وقت) {
        frm.set_df_property('custom_موعد_المتابعة_القادمة_وقت', 'hidden', 0);
        frm.set_df_property('custom_موعد_المتابعة_القادمة_وقت', 'read_only', 1);
        frm.set_df_property('custom_موعد_المتابعة_القادمة_وقت', 'label', 'موعد المتابعة القادم — موحد');
        frm.set_df_property('custom_موعد_المتابعة_القادمة_وقت', 'description', 'القيمة الموحدة التي تعتمد عليها شاشة المتابعة والتنبيهات.');
    }
};

frappe.ui.form.on('Quotation', {
