// Keep helpers local to this Client Script.
;(() => {
const ast_party_map = {
    'عميل': 'Customer',
    'مورد': 'Supplier',
    'موظف': 'Employee'
};

const ast_apply_simple_layout = (frm) => {
    if (frappe.meta.get_docfield('Account Statement', 'company')) {
        frm.set_df_property('company', 'hidden', true);
        frm.set_df_property('company', 'read_only', true);
    }
    const type = frm.doc.statement_type || 'عميل';
    const labels = {عميل:'اسم العميل', مورد:'اسم المورد', موظف:'اسم الموظف', حساب:'اسم الحساب'};
    const active = {عميل:'customer', مورد:'supplier', موظف:'employee', حساب:'account'}[type];
    ['customer','supplier','employee','account'].forEach(field => {
        if (frm.fields_dict[field]) frm.set_df_property(field, 'label', labels[type] || field);
    });
    if (active && frm.fields_dict[active]) frm.set_df_property(active, 'label', labels[type]);
};

const ast_target_visibility = (frm) => {
    const type = frm.doc.statement_type;
    const fields = {
        customer: type !== 'عميل',
        supplier: type !== 'مورد',
        employee: type !== 'موظف',
        account: type !== 'حساب'
    };
    Object.entries(fields).forEach(([field, hidden]) => {
        if (frappe.meta.get_docfield('Account Statement', field)) {
            frm.set_df_property(field, 'hidden', hidden);
            frm.set_df_property(field, 'reqd', !hidden);
        }
    });
    if (type === 'حساب') {
        frm.set_df_property('account', 'description', 'اختر حسابًا تفصيليًا مثل الإيجارات أو المرتبات أو المصروفات أو البنك.');
        frm.set_query('account', () => ({
            filters: { company: frm.doc.company || 'Solar City', is_group: 0, disabled: 0 }
        }));
    }
};

const ast_get_target_filters = (frm) => {
    const type = frm.doc.statement_type;
    if (!type) throw new Error('اختر نوع الكشف أولًا.');
    if (type === 'حساب') {
        if (!frm.doc.account) throw new Error('اختر الحساب المطلوب استخراج كشفه.');
        return {account: [frm.doc.account]};
    }
    const field = {عميل:'customer', مورد:'supplier', موظف:'employee'}[type];
    const party = frm.doc[field];
    if (!party) throw new Error('اختر '+type+' المطلوب استخراج كشفه.');
    return {party_type: ast_party_map[type], party: [party]};
};

const ast_run_gl = async (filters) => {
    const r = await frappe.call({
        method: 'frappe.desk.query_report.run',
        args: {
            report_name: 'General Ledger',
            filters: JSON.stringify(Object.assign({include_default_book_entries: 1}, filters))
        }
    });
    if (r.exc) throw new Error('تعذر قراءة الأستاذ العام.');
    return r.message || {};
};

const ast_num = v => Number(v || 0) || 0;
const ast_prev_date = date => frappe.datetime.add_days(date, -1);

const ast_invoice_cache = {};
const ast_voucher_description_cache = {};
const ast_get_voucher_description = async (voucher_type, voucher_no) => {
    if (!voucher_type || !voucher_no) return '';
    const key = voucher_type + '|' + voucher_no;
    if (Object.prototype.hasOwnProperty.call(ast_voucher_description_cache, key)) return ast_voucher_description_cache[key];
    try {
        const r = await frappe.call({method: 'frappe.client.get', args: {doctype: voucher_type, name: voucher_no}});
        const doc = r.message || {};
        // أولوية العرض: الاسم التشغيلي المتسلسل للمستند، ثم البيان اليدوي، ثم الحقول الوصفية العامة.
        const display_name = doc.custom_customer_document_title || doc.custom_supplier_document_title || '';
        const description = display_name || doc.user_remark || doc.remarks || doc.remark || doc.description || doc.narration || doc.title || '';
        ast_voucher_description_cache[key] = description;
        return description;
    } catch (e) {
        ast_voucher_description_cache[key] = '';
        return '';
    }
};
const ast_get_invoice = async (voucher_type, voucher_no) => {
    if (!['Sales Invoice', 'Purchase Invoice'].includes(voucher_type) || !voucher_no) return null;
    const key = voucher_type + '|' + voucher_no;
    if (ast_invoice_cache[key]) return ast_invoice_cache[key];
    try {
        const r = await frappe.call({method: 'frappe.client.get', args: {doctype: voucher_type, name: voucher_no}});
        if (r.message) ast_invoice_cache[key] = r.message;
        return r.message || null;
    } catch (e) {
        return null;
    }
};

const ast_invoice_header = (row, invoice, running, debit, credit) => ({
    row_type: 'فاتورة',
    posting_date: row.posting_date,
    voucher_type: row.voucher_type || '',
    voucher_no: row.voucher_no || '',
    group_label: (row.voucher_type || '') + ' — ' + (row.voucher_no || ''),
    remarks: invoice.custom_customer_document_title || invoice.custom_supplier_document_title || invoice.remarks || invoice.customer_name || invoice.supplier_name || 'فاتورة',
    account: row.account || '',
    party_type: row.party_type || '',
    party: row.party || invoice.customer || invoice.supplier || '',
    debit,
    credit,
    balance: running,
    project: row.project || '',
    cost_center: row.cost_center || ''
});

const ast_invoice_item_row = (row, invoice, item, running) => ({
    row_type: 'بند فاتورة',
    posting_date: row.posting_date,
    voucher_type: row.voucher_type || '',
    voucher_no: row.voucher_no || '',
    group_label: '',
    remarks: item.item_name || item.item_code || item.description || 'بند فاتورة',
    account: '',
    party_type: row.party_type || '',
    party: row.party || invoice.customer || invoice.supplier || '',
    qty: ast_num(item.qty),
    uom: item.uom || item.stock_uom || '',
    unit_price: ast_num(item.rate),
    custom_item_code: item.item_code || '',
    custom_item_name: item.item_name || '',
    custom_item_description: item.description || '',
    custom_discount_percentage: ast_num(item.discount_percentage),
    custom_item_amount: ast_num(item.amount),
    debit: 0,
    credit: 0,
    balance: running,
    project: item.project || row.project || '',
    cost_center: item.cost_center || row.cost_center || ''
});

const ast_generate = async (frm) => {
    if (!frm.doc.company) await frm.set_value('company', 'Solar City');
    if (!frm.doc.from_date || !frm.doc.to_date) throw new Error('أدخل تاريخ البداية وتاريخ النهاية.');
    if (frm.doc.from_date > frm.doc.to_date) throw new Error('تاريخ البداية يجب أن يسبق تاريخ النهاية.');
    const target = ast_get_target_filters(frm);
    const base = Object.assign({company: frm.doc.company}, target);
    const current = await ast_run_gl(Object.assign(base, {from_date: frm.doc.from_date, to_date: frm.doc.to_date}));
    let opening = 0;
    if (frm.doc.include_opening) {
        const previous = await ast_run_gl(Object.assign(base, {from_date: '1900-01-01', to_date: ast_prev_date(frm.doc.from_date)}));
        opening = (previous.result || []).reduce((sum, row) => sum + ast_num(row.debit) - ast_num(row.credit), 0);
    }
    const raw_source = (current.result || []).filter(row => row.posting_date || row.voucher_no);
    // تجميع سطور الأستاذ العام لنفس المستند حتى لا تتكرر الفاتورة عند تعدد حسابات القيد.
    const raw_index = new Map();
    for (const entry of raw_source) {
        const key = [entry.posting_date || '', entry.voucher_type || '', entry.voucher_no || ''].join('|');
        if (!raw_index.has(key)) raw_index.set(key, Object.assign({}, entry));
        else {
            const existing = raw_index.get(key);
            existing.debit = ast_num(existing.debit) + ast_num(entry.debit);
            existing.credit = ast_num(existing.credit) + ast_num(entry.credit);
        }
    }
    const raw = Array.from(raw_index.values());
    const grouped = [];
    let debit_total = 0;
    let credit_total = 0;
    let running = opening;
    let active_key = null;
    let group_rows = [];
    const flush_group = () => {
        if (!group_rows.length) return;
        const g_debit = group_rows.reduce((s, x) => s + ast_num(x.debit), 0);
        const g_credit = group_rows.reduce((s, x) => s + ast_num(x.credit), 0);
        grouped.push({
            row_type: 'إجمالي مجموعة',
            group_label: 'إجمالي المجموعة',
            remarks: 'إجمالي المستند',
            group_debit_total: g_debit,
            group_credit_total: g_credit,
            debit: g_debit,
            credit: g_credit,
            balance: group_rows[group_rows.length - 1].balance
        });
        group_rows = [];
    };
    for (const row of raw) {
        const key = [row.posting_date || '', row.voucher_type || '', row.voucher_no || ''].join('|');
        if (active_key !== null && key !== active_key) flush_group();
        active_key = key;
        const debit = ast_num(row.debit);
        const credit = ast_num(row.credit);
        debit_total += debit;
        credit_total += credit;
        running += debit - credit;
        const invoice = await ast_get_invoice(row.voucher_type, row.voucher_no);
        if (invoice && (invoice.items || []).length) {
            const header = ast_invoice_header(row, invoice, running, debit, credit);
            grouped.push(header);
            group_rows.push(header);
            for (const item of invoice.items) grouped.push(ast_invoice_item_row(row, invoice, item, running));
        } else {
            const mapped = {
                row_type: 'حركة',
                posting_date: row.posting_date,
                voucher_type: row.voucher_type || '',
                voucher_no: row.voucher_no || '',
                group_label: (row.voucher_type || '') + (row.voucher_no ? ' — '+row.voucher_no : ''),
                remarks: (await ast_get_voucher_description(row.voucher_type, row.voucher_no)) || row.remarks || row.against || row.voucher_subtype || row.account || '',
                account: row.account,
                party_type: row.party_type || '',
                party: row.party || row.party_name || '',
                debit,
                credit,
                balance: running,
                project: row.project || '',
                cost_center: row.cost_center || ''
            };
            grouped.push(mapped);
            group_rows.push(mapped);
        }
    }
    flush_group();
    frm.clear_table('rows');
    grouped.forEach(row => frm.add_child('rows', row));
    const closing = opening + debit_total - credit_total;
    let status = 'متزن';
    if (frm.doc.statement_type === 'حساب') status = closing > 0 ? 'مدين' : closing < 0 ? 'دائن' : 'متزن';
    else status = closing > 0 ? 'عليه' : closing < 0 ? 'له' : 'متزن';
    frm.doc.opening_balance = opening;
    frm.doc.total_debit = debit_total;
    frm.doc.total_credit = credit_total;
    frm.doc.closing_balance = closing;
    frm.doc.balance_status = status;
    frm.doc.generated_on = frappe.datetime.now_datetime();
    frm.doc.generated_by = frappe.session.user;
    frm.doc.report_status = 'تم التوليد';
    await frm.save();
    frm.refresh_field('rows');
    frappe.show_alert({message: 'تم توليد كشف الحساب التفصيلي: '+raw.length+' مستندًا و'+grouped.filter(x => x.row_type === 'بند فاتورة').length+' بند فاتورة.', indicator: 'green'});
};

const ast_print = (frm, format_name = 'Account Statement - Solar City') => {
    if (!frm.doc.name || frm.is_dirty()) {
        frappe.msgprint('احفظ الكشف أولًا قبل الطباعة.');
        return;
    }
    const url = '/printview?doctype=Account%20Statement&name='+encodeURIComponent(frm.doc.name)+'&format='+encodeURIComponent(format_name)+'&no_letterhead=1';
    window.open(url, '_blank');
};

frappe.ui.form.on('Account Statement', {
    onload(frm) {
        if (!frm.doc.company) frm.set_value('company', 'Solar City');
        if (!frm.doc.from_date) frm.set_value('from_date', frappe.datetime.year_start());
        if (!frm.doc.to_date) frm.set_value('to_date', frappe.datetime.get_today());
        if (!frm.doc.statement_type) frm.set_value('statement_type', 'عميل');
        ast_target_visibility(frm);
        ast_apply_simple_layout(frm);
    },
    refresh(frm) {
        ast_target_visibility(frm);
        ast_apply_simple_layout(frm);
        frm.remove_custom_button('توليد كشف الحساب');
        frm.remove_custom_button('طباعة كشف الحساب');
        frm.remove_custom_button('طباعة كشف الحساب - Modern');
        frm.add_custom_button('توليد كشف الحساب', async () => {
            try { await ast_generate(frm); } catch (e) { frappe.msgprint(e.message || String(e)); }
        }, 'كشف الحساب');
        if (!frm.is_new() && frm.doc.report_status === 'تم التوليد') {
            frm.add_custom_button('طباعة كشف الحساب', () => ast_print(frm, 'Account Statement - Solar City'), 'كشف الحساب');
            frm.add_custom_button('طباعة كشف الحساب - Modern', () => ast_print(frm, 'Account Statement - Solar City Modern'), 'كشف الحساب');
        }
    },
    statement_type(frm) {
        ast_target_visibility(frm);
        ast_apply_simple_layout(frm);
        ['customer','supplier','employee','account'].forEach(f => frm.set_value(f, null));
    }
});
})();

// Keep helpers local to this Client Script.
;(() => {
const solarcity_open_invoice = (name) => { if (name) frappe.set_route('Form', 'Sales Invoice', name); };

const solarcity_execute_quotation = async (frm) => {
    if (frm.doc.docstatus !== 1) {
        frappe.msgprint({title: 'لا يمكن التنفيذ', indicator: 'orange', message: 'يجب اعتماد عرض السعر أولًا قبل تحويله إلى فاتورة مبيعات.'});
        return;
    }
    if (frm.doc.custom_sales_invoice) {
        solarcity_open_invoice(frm.doc.custom_sales_invoice);
        return;
    }
    frappe.confirm('سيتم إنشاء فاتورة مبيعات مرتبطة بهذا العرض. إذا كانت لديك صلاحية الحسابات سيتم ترحيل الفاتورة، وإلا ستُحفظ كمسودة للمراجعة. هل تريد المتابعة؟', async () => {
        frappe.dom.freeze('جاري إنشاء فاتورة المبيعات...');
        try {
            const old = await frappe.call({method: 'frappe.client.get_list', args: {doctype: 'Sales Invoice', fields: ['name', 'docstatus'], filters: {custom_quotation: frm.doc.name}, limit_page_length: 1}});
            if ((old.message || []).length) {
                const old_name = old.message[0].name;
                await frappe.call({method: 'frappe.client.set_value', args: {doctype: 'Quotation', name: frm.doc.name, fieldname: 'custom_sales_invoice', value: old_name}});
                await frm.reload_doc();
                solarcity_open_invoice(old_name);
                return;
            }
            const mapped = await frappe.call({method: 'erpnext.selling.doctype.quotation.quotation.make_sales_invoice', args: {source_name: frm.doc.name}});
            const invoice = mapped.message;
            invoice.custom_quotation = frm.doc.name;
            invoice.posting_date = frappe.datetime.get_today();
            invoice.set_posting_time = 1;
            const inserted = await frappe.call({method: 'frappe.client.insert', args: {doc: invoice}});
            const created = inserted.message;
            let posted = false;
            const can_post = frappe.user.has_role('Accounts User') || frappe.user.has_role('Accounts Manager') || frappe.user.has_role('System Manager');
            if (can_post) {
                try {
                    await frappe.call({method: 'frappe.client.submit', args: {doc: created}});
