    const rgb = PDFLib.rgb;
    const format = selectQuotationFormat(frm.doc);
    const qUrl = '/api/method/frappe.utils.print_format.download_pdf?doctype=Quotation&name=' + encodeURIComponent(frm.doc.name) + '&format=' + encodeURIComponent(format) + '&no_letterhead=0&hide_valid_till=1&solar_attachment=1';
    const quotationBytes = await fetchBytes(qUrl);
    const attachmentBytes = await fetchBytes(attachmentUrl);
    const quotationPdf = await PDFDocument.load(quotationBytes);
    const attachmentPdf = await PDFDocument.load(attachmentBytes);
    const quotationIndexes = await meaningfulPageIndices(quotationBytes, true);
    const attachmentIndexes = await meaningfulPageIndices(attachmentBytes, false);
    const merged = await PDFDocument.create();
    const targetPage = quotationPdf.getPage(quotationIndexes[0] ?? 0);
    const targetWidth = targetPage.getWidth();
    const targetHeight = targetPage.getHeight();

    const quotationPages = await merged.copyPages(quotationPdf, quotationIndexes);
    quotationPages.forEach(page => merged.addPage(page));
    // Hide valid-till in the print request only; ordinary printing remains unchanged.
    const headerData = await embedLetterHead(merged, targetWidth, targetHeight);
    const footerDataUri = await makeFooterPng();
    const footerImage = await merged.embedPng(dataUriToBytes(footerDataUri));
    const footerFit = footerImage.scaleToFit(targetWidth - 30, Math.min(75, targetHeight * 0.105));
    const header = { image: headerData.image, width: headerData.width, height: headerData.height };
    const footer = { image: footerImage, width: footerFit.width, height: footerFit.height };

    const brandedPages = await brandedAttachmentPageFlags(attachmentBytes, attachmentIndexes);
    for (const index of attachmentIndexes) {
      if (brandedPages[index]) {
        const copied = await merged.copyPages(attachmentPdf, [index]);
        copied.forEach(page => merged.addPage(page));
      } else {
        await addWrappedAttachmentPage(merged, attachmentPdf.getPage(index), header, footer, targetWidth, targetHeight, rgb);
      }
    }

    if (!quotationIndexes.length && !attachmentIndexes.length) throw new Error('لا توجد صفحات قابلة للعرض في العرض أو المرفق');
    const bytes = await merged.save();
    const blobUrl = URL.createObjectURL(new Blob([bytes], { type: 'application/pdf' }));
    const link = document.createElement('a');
    link.href = blobUrl;
    link.download = quotationFilename(frm.doc);
    link.target = '_blank';
    link.rel = 'noopener';
    document.body.appendChild(link);
    link.click();
    link.remove();
    setTimeout(() => URL.revokeObjectURL(blobUrl), 120000);
    frappe.show_alert({ message: 'تم تجهيز العرض والمرفق بدون الصفحات البيضاء.', indicator: 'green' }, 7);
  }

  async function downloadStandardQuotation(doc) {
    const format = selectQuotationFormat(doc);
    const params = new URLSearchParams({
      doctype: 'Quotation',
      name: doc.name,
      format,
      no_letterhead: '0'
    });
    const response = await fetch('/api/method/frappe.utils.print_format.download_pdf?' + params.toString(), { credentials: 'same-origin' });
    if (!response.ok) throw new Error('HTTP ' + response.status + ' while downloading the quotation');
    const blob = await response.blob();
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = quotationFilename(doc);
    link.style.display = 'none';
    document.body.appendChild(link);
    link.click();
    setTimeout(() => { link.remove(); URL.revokeObjectURL(url); }, 1500);
  }

  function standardPrint(frm) {
    const format = selectQuotationFormat(frm.doc);
    return frappe.set_route('print', frm.doctype, frm.doc.name, { print_format: format, format });
  }

  async function solarQuotationPrint(frm) {
    if (frm.is_new() || frm.is_dirty()) {
      frappe.msgprint({ title: 'احفظ العرض أولًا', indicator: 'orange', message: 'احفظ عرض السعر قبل استخدام زر الطباعة.' });
      return;
    }
    const attachment = await resolveTechnicalPdf(frm); if (!attachment) { standardPrint(frm); return; } if (!looksLikePdf(attachment.file_name) && !looksLikePdf(attachment.url)) { frappe.msgprint({title:'الملف غير صالح',indicator:'red',message:'المرفق المرتبط بالعرض يجب أن يكون ملف PDF فقط.'}); return; }     frappe.show_alert({ message: 'جاري تجهيز العرض وتنظيف الصفحات البيضاء وإضافة الملف الفني...', indicator: 'blue' }, 6);
    try {
      await downloadMergedQuotation(frm, attachment.url);
    } catch (e) {
      console.error('Solar City quotation PDF merge failed', e);
      frappe.msgprint({ title: 'تعذر تجهيز الملف المدمج', indicator: 'red', message: 'تعذر دمج ملف PDF المرفق. راجع أن الملف صالح وأنه قابل للقراءة، ثم أعد المحاولة.' });
    }
  }

  function patchStandardPrint(frm) {
    const root = frm && frm.page && frm.page.wrapper && (frm.page.wrapper[0] || frm.page.wrapper);
    if (!root || !root.addEventListener) return;
    if (root.dataset.solarPrintDelegated === '1') return;
    root.addEventListener('click', function (event) {
      const link = event.target && event.target.closest ? event.target.closest('a.dropdown-item') : null;
      if (!link || (link.innerText || '').trim() !== 'طباعة') return;
      event.preventDefault();
      event.stopImmediatePropagation();
      solarQuotationPrint(frm);
      return false;
    }, true);
    root.dataset.solarPrintDelegated = '1';
  }

  function getPrintviewQuotationName(){const m=location.pathname.match(/\/app\/print\/Quotation\/([^/?#]+)/);return m?decodeURIComponent(m[1]):'';}
  async function preparePrintviewQuotation(){
    if(!location.pathname.includes('/app/print/Quotation/'))return null;
    const name=getPrintviewQuotationName();if(!name)return null;
    if(window.__solarPrintviewPreparation)return window.__solarPrintviewPreparation;
    window.__solarPrintviewPreparation=(async()=>{
      try{
        const r=await frappe.xcall('frappe.client.get',{doctype:'Quotation',name});
        const pseudo={doctype:'Quotation',doc:r,is_new:()=>false,is_dirty:()=>false};
        const attachment=await resolveTechnicalPdf(pseudo);
        window.__solarPrintviewQuotation=pseudo;
        window.__solarPrintviewAttachment=attachment||null;
        const filename=quotationFilename(r);
        document.title=filename.replace(/\.pdf$/i,'');
        document.querySelectorAll('a[href*="download_pdf"]').forEach(link=>link.setAttribute('download',filename));
        patchPrintviewPrintButton();
        return pseudo;
      }catch(e){
        console.warn('Solar City: printview preparation failed',e);
        window.__solarPrintviewQuotation=null;
        window.__solarPrintviewAttachment=null;
        return null;
      }
    })();
    return window.__solarPrintviewPreparation;
  }
  async function printviewQuotationPrint(){
    const pseudo=window.__solarPrintviewQuotation||await preparePrintviewQuotation();
    const attachment=window.__solarPrintviewAttachment;
    if(!pseudo){
      frappe.msgprint({ title: 'تعذر تجهيز العرض', indicator: 'red', message: 'تعذر قراءة بيانات عرض السعر، لذلك لم تتم طباعة واجهة المعاينة.' });
      return;
    }
    if(!attachment){
      // اترك معاينة ERPNext القياسية كما هي عند عدم وجود مرفق.
      return;
    }
    try{
      frappe.show_alert({message:'جاري تجهيز العرض والمرفق...',indicator:'blue'},5);
      if(!looksLikePdf(attachment.file_name)&&!looksLikePdf(attachment.url)){frappe.msgprint({title:'الملف غير صالح',indicator:'red',message:'المرفق المرتبط بالعرض يجب أن يكون PDF.'});return;}
      await downloadMergedQuotation(pseudo,attachment.url);
    }catch(e){
      console.error('Solar printview merge failed',e);
      frappe.msgprint({title:'تعذر تجهيز الملف المدمج',indicator:'red',message:'تعذر إلحاق ملف PDF المرفق.'});
    }
  }
  function syncPrintviewFormat(){
    if(!location.pathname.includes('/app/print/Quotation/'))return;
    const pseudo=window.__solarPrintviewQuotation;
    if(!pseudo||!pseudo.doc)return;
    const input=document.querySelector('input[data-fieldname="print_format"]');
    if(!input)return;
    if(input.dataset.solarPrintFormatUserChanged==='1')return;
    const wanted=selectQuotationFormat(pseudo.doc);
    if(!wanted||String(input.value||'').trim())return;
    input.value=wanted;
    if(window.jQuery) window.jQuery(input).trigger('change');
    else input.dispatchEvent(new Event('change',{bubbles:true}));
  }
  function patchPrintviewPrintButton(){
    if(!location.pathname.includes('/app/print/Quotation/'))return;
    if(window.__solarPrintviewAttachment===undefined){preparePrintviewQuotation();return;}
    syncPrintviewFormat();
    ensureSolarPrintFormatOptions();
    if(!window.__solarPrintviewAttachment)return;
    const bs=[...document.querySelectorAll('button')].filter(b=>(b.innerText||'').trim()==='طباعة');
    bs.forEach(b=>{if(b.dataset.solarPrintviewButton==='1')return;b.dataset.solarPrintviewButton='1';b.addEventListener('click',function(e){e.preventDefault();e.stopImmediatePropagation();printviewQuotationPrint();return false;},true);});
  }
  function ensureSolarPrintFormatOptions() {
    if (!location.pathname.includes('/app/print/Quotation/')) return;
    if (!window.Awesomplete || !Array.isArray(window.Awesomplete.all)) { setTimeout(ensureSolarPrintFormatOptions, 250); return; }
    const input = document.querySelector('input[data-fieldname="print_format"]');
    if (!input) { setTimeout(ensureSolarPrintFormatOptions, 250); return; }
    const instance = window.Awesomplete.all.find(item => item && item.input === input);
    if (!instance) { setTimeout(ensureSolarPrintFormatOptions, 250); return; }
    if (input.dataset.solarPrintFormatRefresh === '1') return;
    const refreshOptions = () => {
      input.dataset.solarPrintFormatRefreshing='1';
      input.value = '';
      try { input.dispatchEvent(new Event('input', { bubbles: true })); } catch (e) {}
      setTimeout(() => { delete input.dataset.solarPrintFormatRefreshing; }, 50);
    };
    input.addEventListener('focus', refreshOptions, true);
    input.addEventListener('click', refreshOptions, true);
    input.addEventListener('input', () => { if(input.dataset.solarPrintFormatRefreshing!=='1') input.dataset.solarPrintFormatUserChanged='1'; }, true);
    input.addEventListener('change', () => { if(input.dataset.solarPrintFormatRefreshing!=='1') input.dataset.solarPrintFormatUserChanged='1'; }, true);
    input.dataset.solarPrintFormatRefresh = '1';
  }


  function installPrintviewObserver(){
    if(!document.body)return;
    preparePrintviewQuotation();
    ensureSolarPrintFormatOptions();
    if(window.__solarPrintviewObserver)return;
    window.__solarPrintviewObserver=new MutationObserver(()=>{patchPrintviewPrintButton();ensureSolarPrintFormatOptions();});
    window.__solarPrintviewObserver.observe(document.body,{childList:true,subtree:true});
    setTimeout(()=>{syncPrintviewFormat();patchPrintviewPrintButton();ensureSolarPrintFormatOptions();},300);
  }

  function maybeInstallPrintviewObserver() {
    try { if (location.pathname.includes('/app/print/Quotation/')) installPrintviewObserver(); } catch (e) { console.warn('Solar printview hook failed', e); }
  }
  setTimeout(maybeInstallPrintviewObserver, 0);
  if (frappe.router && typeof frappe.router.on === 'function') {
    frappe.router.on('change', maybeInstallPrintviewObserver);
  }

  frappe.ui.form.on('Quotation', {
    onload(frm) {
      patchStandardPrint(frm);
    },
    refresh(frm) {
      patchStandardPrint(frm);
    },
    validate(frm) {
      const value = frm.doc.custom_technical_pdf;
      if (value && !/\.pdf(?:$|[?#])/i.test(value)) {
        frappe.throw('الملف الفني يجب أن يكون بصيغة PDF فقط.');
      }
    }
  });
})();
})();

