        const pages=(await frappe.call({method:'frappe.client.get_list',args:{doctype:'Web Page',filters:{route:'solar-city-company-customer-catalog'},fields:['name'],limit_page_length:1}})).message||[];
        if(!pages.length)throw new Error('صفحة العميل العامة غير موجودة');
        const page=(await frappe.call({method:'frappe.client.get',args:{doctype:'Web Page',name:pages[0].name}})).message;
        page.main_section_html='<div id="scc-root" data-config="'+esc+'"></div>';
        await frappe.call({method:'frappe.client.save',args:{doc:page}});
        frappe.show_alert({message:'تم نشر القائمة وتحديث رابط العميل.',indicator:'green'});
      }catch(e){frappe.msgprint('تعذر نشر القائمة: '+(e.message||e));}
    });
  }
});


